"""Item reference tables, generated from reference/itemdat.cpp
and reference/enums.h by scripts/gen_itemdata.py -- do not hand-edit.
Regenerate with: python scripts/gen_itemdata.py"""

from dataclasses import dataclass
from typing import Optional


@dataclass(frozen=True)
class ItemData:
    idx: int
    enum_name: Optional[str]  # e.g. 'IDI_GOLD'; None for unnamed regular-drop items
    name: Optional[str]
    short_name: Optional[str]
    i_class: int       # ICLASS_*
    i_loc: int         # ILOC_* -- matches raw ItemStruct._iLoc directly
    i_curs: int        # ICURS_* -- matches raw ItemStruct._iCurs directly
    i_type: int        # ITYPE_* -- matches raw ItemStruct._itype directly
    unique_type: Optional[str]  # UITYPE_* symbol, or None (UITYPE_NONE)
    min_level: int
    durability: int
    min_damage: int
    max_damage: int
    min_ac: int
    max_ac: int
    min_str: int
    min_mag: int
    min_dex: int
    flags: int         # ISPL_* bitmask -- matches raw ItemStruct._iFlags
    misc_id: int       # IMISC_* -- matches raw ItemStruct._iMiscId
    spell: int         # SPL_*
    usable: bool
    value: int
    max_value: int
    width_cells: int   # real backpack-grid footprint, from reference/cursor.cpp's InvItemWidth[]
    height_cells: int  # ...InvItemHeight[]; both /28 already applied


@dataclass(frozen=True)
class UniqueItemData:
    position: int      # index into UNIQUE_ITEMS -- what a quest item's iSeed points to directly
    name: str
    item_type: str     # UITYPE_* symbol -- cross-reference to ItemData.unique_type
    min_level: int
    num_powers: int
    value: int
    powers: tuple       # ((power_symbol, param1, param2), ...) -- up to 6; game-engine-applied, not reimplemented here


